    zero_rows = [r for r in range(h) if all(grid[r][c] == 0 for c in range(w))]
    zero_cols = [c for c in range(w) if all(grid[r][c] == 0 for r in range(h))]
    horizontal = len(zero_rows) >= len(zero_cols)
    out = [[7] * w for _ in range(h)]
    if horizontal:
        m = (min(rs) + max(rs)) // 2
        center = (min(cs) + max(cs)) // 2
        start = center - n // 2
        out[m - 1] = [0] * w
        out[m + 1] = [0] * w
        for c in range(w):
            if sum(grid[r][c] == 0 for r in range(h)) > len(zero_rows):
                for r in range(h):
                    out[r][c] = 0
        for c in range(start, start + n):
            out[m][c] = 5
    else:
        m = (min(cs) + max(cs)) // 2
        center = (min(rs) + max(rs)) // 2
        start = center - n // 2
        for r in range(h):
            out[r][m - 1] = out[r][m + 1] = 0
        for r in range(h):
            if sum(grid[r][c] == 0 for c in range(w)) > len(zero_cols):
                out[r] = [0] * w
        for r in range(start, start + n):
            out[r][m] = 5
    return out
